def txt(sl,x,y,w,h,t,size=22,bold=False,color='F5F5F0'):
 sh=sl.shapes.add_textbox(Inches(x),Inches(y),Inches(w),Inches(h));tf=sh.text_frame;tf.word_wrap=True
 for i,line in enumerate(t.split('\n')):
  p=tf.paragraphs[0] if i==0 else tf.add_paragraph();p.text=line;p.font.name='Calibri';p.font.size=Pt(size);p.font.bold=bold;p.font.color.rgb=RGBColor.from_string(color);p.space_after=Pt(15)
 return sh
for i,(title,claim,body,notes) in enumerate(slides):
 sl=prs.slides.add_slide(prs.slide_layouts[6]);sl.shapes.add_picture(str(R/'tmp/interview-background.png'),0,0,width=prs.slide_width,height=prs.slide_height)
 txt(sl,.6,.25,12.1,.45,'CADENCE FINANCIAL GROUP  /  CASE STUDY 02',13,True)
 txt(sl,.65,1.02,12,1.0,title,32,True)
 txt(sl,.7,2.02,11.9,.65,claim,21,False,'BFCBD2')
 box=sl.shapes.add_shape(MSO_SHAPE.RECTANGLE,Inches(.65),Inches(2.9),Inches(12.0),Inches(3.7));box.fill.background();box.line.color.rgb=RGBColor(240,240,235);box.line.width=Pt(1)
 txt(sl,.93,3.12,11.4,3.3,body,21)
 txt(sl,.7,6.95,11,.3,'Text analysis and PII detection | Interview walkthrough' if i<21 else 'Technical discussion | Reference slides',11,False,'BFCBD2')
 txt(sl,12,6.95,.6,.3,f'{i+1:02}',11)
 sl.notes_slide.notes_text_frame.text=notes
prs.save(out)
# Preview every slide from identical layout geometry and font metrics.
preview=R/'tmp/interview-preview';preview.mkdir(exist_ok=True)
for i,sl in enumerate(prs.slides):
 im=bg.resize((1280,720));d=ImageDraw.Draw(im)
 for sh in sl.shapes:
  x,y,w,h=[int(v/914400*96) for v in (sh.left,sh.top,sh.width,sh.height)]
  if sh.shape_type==1:d.rectangle((x,y,x+w,y+h),outline='#f0f0eb',width=1)
  if not sh.has_text_frame or not sh.text:continue
  yy=y+4
  for p in sh.text_frame.paragraphs:
   f=ImageFont.truetype('C:/Windows/Fonts/calibrib.ttf' if p.font.bold else 'C:/Windows/Fonts/calibri.ttf',int(p.font.size.pt*96/72));line='';lines=[]
   for word in p.text.split():
    n=(line+' '+word).strip()
    if line and d.textlength(n,font=f)>w-20:lines.append(line);line=word
    else:line=n
   lines.append(line)
   for line in lines:d.text((x+9,yy),line,font=f,fill=tuple(p.font.color.rgb));yy+=int(p.font.size.pt*96/72*1.16)
   yy+=20
  assert yy<=y+h+24,(i+1,sh.text[:40],yy,y+h)
 im.save(preview/f'{i+1:02}.png')
for start in range(0,len(slides),6):
 contact=Image.new('RGB',(960,810),'#ccc')
 for j in range(start,min(start+6,len(slides))):
  im=Image.open(preview/f'{j+1:02}.png');im.thumbnail((480,270));contact.paste(im,((j-start)%2*480,(j-start)//2*270))
 contact.save(preview/f'contact-{start}.jpg')
